# Simple HTTP server for static files using HttpListener\n$port = 8000\n$listener = [System.Net.HttpListener]::new()\n$listener.Prefixes.Add("http://localhost:$port/")\n$listener.Start()\nWrite-Host "Serving files from $(Get-Location) on http://localhost:$port"\nwhile ($listener.IsListening) {\n    $context = $listener.GetContext()\n    $request = $context.Request\n    $response = $context.Response\n    $localPath = $request.Url.AbsolutePath.TrimStart('/')\n    if ([string]::IsNullOrEmpty($localPath)) { $localPath = 'index.html' }\n    $fullPath = Join-Path (Get-Location) $localPath\n    if (Test-Path $fullPath -PathType Leaf) {\n        $bytes = [System.IO.File]::ReadAllBytes($fullPath)\n        $response.ContentLength64 = $bytes.Length\n        $mime = switch -regex ($fullPath) {\n            '\\.html$' { 'text/html' }\n            '\\.css$' { 'text/css' }\n            '\\.js$' { 'application/javascript' }\n            '\\.json$' { 'application/json' }\n            '\\.png$' { 'image/png' }\n            '\\.jpg$' { 'image/jpeg' }\n            default { 'application/octet-stream' }\n        }\n        $response.ContentType = $mime\n        $response.OutputStream.Write($bytes,0,$bytes.Length)\n    } else {\n        $response.StatusCode = 404\n        $msg = "404 Not Found"\n        $bytes = [System.Text.Encoding]::UTF8.GetBytes($msg)\n        $response.ContentLength64 = $bytes.Length\n        $response.OutputStream.Write($bytes,0,$bytes.Length)\n    }\n    $response.OutputStream.Close()\n}\n$listener.Stop()